corporate_design.toad_component_blueprint:
canvas {
  size: 960px 560px;
  fill: #111827;
  font-family: "Barlow, sans-serif";
}

>roadDark = #111827;
>amber = #F59E0B;
>routeCyan = #0284C7;
>cardSurface = #1F2937;

rect #truckCard {
  at: center of canvas;
  size: 880px 460px;
  fill: >cardSurface;
  stroke: #374151;
  stroke-width: 1px;
  radius: 6px;
}

text #truckHeader {
  at: top left of #truckCard offset 32px 28px;
  content: "OMNIDRIVE FLEET // LKW-42 • MAN TGX 18.510";
  font-size: 16px;
  font-weight: 700;
  color: #FFFFFF;
}

text #gpsLocation {
  at: below #truckHeader offset 10px;
  content: "A3 NÜRNBERG -> FRANKFURT • KM 182.4 • 84 KM/H";
  font-size: 13px;
  color: >routeCyan;
}

rect #fuelWarning {
  at: below #gpsLocation offset 24px;
  size: 320px 48px;
  fill: alpha(>amber, 0.15);
  stroke: >amber;
  stroke-width: 1px;
  radius: 4px;
}

text #fuelText {
  at: center of #fuelWarning;
  content: "RESTREICHWEITE: 140 KM • TANKEN";
  font-size: 12px;
  font-weight: 700;
  color: >amber;
}
